import { NextRequest, NextResponse } from "next/server";
import { mcpTokenMayStartRun } from "@/lib/thread-access";
import { verifyMcpToken, resolveBoundAgentId } from "@/lib/mcp";
import { consumeRateLimit } from "@/lib/rate-limit";
import { insertRunStart, startRunSchema, payloadTooLarge } from "@/lib/run-ledger";

/** Runtime turns are frequent but bounded; leave room for a busy fleet. */
const RUNS_PER_MINUTE = 2_000;

/**
 * POST /api/mcp/agents/runs — open a run (or return the existing one).
 *
 * The `id` is generated by the runtime, so start is idempotent: a repeat start
 * for the same id is a no-op that returns the stored row. Company-scoped, and a
 * token bound to an agent may only open runs for that agent.
 */
export async function POST(req: NextRequest) {
    const auth = await verifyMcpToken(req);
    if (auth.error) return NextResponse.json({ error: auth.error }, { status: auth.status });
    const companyId = auth.companyToken!.companyId;

    const raw = await req.text();
    if (payloadTooLarge(raw)) return NextResponse.json({ error: "Payload too large" }, { status: 413 });

    let body: unknown;
    try {
        body = JSON.parse(raw);
    } catch {
        return NextResponse.json({ error: "Request body must be valid JSON" }, { status: 400 });
    }
    const parsed = startRunSchema.safeParse(body);
    if (!parsed.success) {
        const issue = parsed.error.issues[0];
        const path = issue && issue.path.length > 0 ? issue.path.join(".") : "body";
        return NextResponse.json({ error: `Invalid request body — ${path}: ${issue?.message ?? "invalid"}` }, { status: 400 });
    }
    const input = parsed.data;

    let effectiveAgentId: string;
    try {
        const resolved = await resolveBoundAgentId(companyId, auth.companyToken!, input.agentId);
        if (!resolved) return NextResponse.json({ error: "agentId is required" }, { status: 400 });
        effectiveAgentId = resolved;
    } catch (err) {
        const msg = err instanceof Error ? err.message : "Access denied";
        return NextResponse.json({ error: msg }, { status: msg.startsWith("Access denied") ? 403 : 404 });
    }

    // A run may only point at a private direct thread when it is that thread's
    // own agent's run (bound token, or the agent a company-wide token names).
    if (!(await mcpTokenMayStartRun(companyId, effectiveAgentId, input))) {
        return NextResponse.json({ error: "Thread not found" }, { status: 404 });
    }

    const limit = consumeRateLimit({
        key: `mcp:runs:${input.runtimeId ?? effectiveAgentId}`,
        limit: RUNS_PER_MINUTE,
        windowMs: 60_000,
    });
    if (!limit.allowed) return NextResponse.json({ error: "Rate limit exceeded" }, { status: 429 });

    try {
        const run = await insertRunStart(companyId, effectiveAgentId, input);
        if (!run) return NextResponse.json({ error: "Run id is already in use" }, { status: 409 });
        return NextResponse.json({ run });
    } catch (error) {
        console.error("runs start error:", error);
        return NextResponse.json({ error: "Internal error" }, { status: 500 });
    }
}
